-- BOROUGH & LEDGER CRM | DATOS OPERATIVOS RELACIONADOS
-- COMPATIBLE: backend empresarial con Flyway V1-V5 (MySQL 8+).
-- Fecha de generación: 2026-10-23.
-- Entorno recomendado: base local de desarrollo, con respaldo previo.
-- NO CREA BASE DE DATOS, NO BORRA TABLAS, NO CAMBIA ADMINISTRADOR NI CLAVES EXISTENTES.
-- Datos de entidades y personas SON FICTICIOS. Emails usan .example y teléfonos no reales.
-- Reejecutable: UUID predecibles y ON DUPLICATE KEY UPDATE id=id (no pisa modificaciones).
-- IMPORTANTE: NO es una migración Flyway: ejecutar una sola vez desde Workbench,
-- y se puede volver a ejecutar sin duplicar las mismas filas.
-- Los colaboradores de prueba se crean DESACTIVADOS con contraseñas aleatorias
-- irreconocibles (no distribuidas): un administrador debe restablecer su contraseña
-- de forma segura ANTES de habilitarlos. Propietario de los negocios = admin actual.
-- Los registros de auditoría insertados solo documentan la importación de clientes.

USE borough_ledger;

-- Si tu administrador no usa este correo, modifícalo aquí (no cambies nada más).
SET @crm_seed_admin_email = 'admin@local.test';

DELIMITER $$
DROP PROCEDURE IF EXISTS seed_borough_ledger_datos_operativos$$
CREATE PROCEDURE seed_borough_ledger_datos_operativos()
BEGIN
  DECLARE v_org VARCHAR(36);
  DECLARE v_admin VARCHAR(36);
  DECLARE v_count INT DEFAULT 0;
  DECLARE v_email VARCHAR(190);
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  SET v_email = COALESCE(NULLIF(TRIM(@crm_seed_admin_email), ''), 'admin@local.test');
  -- Verificación de migraciones y cuenta propietaria antes de escribir.
  SELECT COUNT(DISTINCT version) INTO v_count
  FROM flyway_schema_history
  WHERE version IN ('1','2','3','4','5') AND success = 1;
  IF v_count <> 5 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Debes ejecutar primero las migraciones Flyway V1-V5';
  END IF;
  SELECT COUNT(*) INTO v_count FROM app_users
  WHERE email = v_email AND role = 'ADMIN' AND enabled = 1;
  IF v_count <> 1 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No existe un administrador activo con el correo indicado';
  END IF;
  SELECT id, organization_id INTO v_admin, v_org
  FROM app_users WHERE email = v_email AND enabled = 1 AND role = 'ADMIN' LIMIT 1;

  START TRANSACTION;

  -- app_users: 10 registros predefinidos.
  ON DUPLICATE KEY UPDATE `id`=`id`;

  -- customers: 12 registros predefinidos.
  ON DUPLICATE KEY UPDATE `id`=`id`;

  -- contacts: 16 registros predefinidos.
  ON DUPLICATE KEY UPDATE `id`=`id`;

  -- leads: 18 registros predefinidos.
  ON DUPLICATE KEY UPDATE `id`=`id`;

  -- pipelines: 10 registros predefinidos.
  ON DUPLICATE KEY UPDATE `id`=`id`;

  -- pipeline_stages: 50 registros predefinidos.
  ON DUPLICATE KEY UPDATE `id`=`id`;

  -- opportunities: 30 registros predefinidos.
  ON DUPLICATE KEY UPDATE `id`=`id`;

  -- opportunity_stage_history: 40 registros predefinidos.
  ON DUPLICATE KEY UPDATE `id`=`id`;

  -- activities: 25 registros predefinidos.
  ON DUPLICATE KEY UPDATE `id`=`id`;

  -- crm_tasks: 25 registros predefinidos.
  ON DUPLICATE KEY UPDATE `id`=`id`;

  -- products: 20 registros predefinidos.
  ON DUPLICATE KEY UPDATE `id`=`id`;

  -- quotations: 20 registros predefinidos.
  ON DUPLICATE KEY UPDATE `id`=`id`;

  -- quotation_items: 60 registros predefinidos.
  ON DUPLICATE KEY UPDATE `id`=`id`;

  -- audit_logs: 12 registros predefinidos.
  ON DUPLICATE KEY UPDATE `id`=`id`;

  COMMIT;

  -- Recuento después de importar: muestra filas de ESTA organización, incluidas previas.
  SELECT 'Usuarios (incluye administrador)' AS modulo, COUNT(*) AS registros FROM app_users WHERE organization_id=v_org
  UNION ALL SELECT 'Clientes', COUNT(*) FROM customers WHERE organization_id=v_org AND archived_at IS NULL
  UNION ALL SELECT 'Contactos', COUNT(*) FROM contacts WHERE organization_id=v_org AND archived_at IS NULL
  UNION ALL SELECT 'Prospectos', COUNT(*) FROM leads WHERE organization_id=v_org AND archived_at IS NULL
  UNION ALL SELECT 'Embudos', COUNT(*) FROM pipelines WHERE organization_id=v_org AND archived_at IS NULL
  UNION ALL SELECT 'Etapas comerciales', COUNT(*) FROM pipeline_stages WHERE organization_id=v_org AND archived_at IS NULL
  UNION ALL SELECT 'Oportunidades', COUNT(*) FROM opportunities WHERE organization_id=v_org AND archived_at IS NULL
  UNION ALL SELECT 'Historial de etapas', COUNT(*) FROM opportunity_stage_history WHERE organization_id=v_org
  UNION ALL SELECT 'Actividades', COUNT(*) FROM activities WHERE organization_id=v_org AND archived_at IS NULL
  UNION ALL SELECT 'Tareas', COUNT(*) FROM crm_tasks WHERE organization_id=v_org AND archived_at IS NULL
  UNION ALL SELECT 'Productos y servicios', COUNT(*) FROM products WHERE organization_id=v_org AND archived_at IS NULL
  UNION ALL SELECT 'Cotizaciones', COUNT(*) FROM quotations WHERE organization_id=v_org AND archived_at IS NULL
  UNION ALL SELECT 'Partidas de cotización', COUNT(*) FROM quotation_items i JOIN quotations q ON q.id=i.quotation_id WHERE q.organization_id=v_org
  UNION ALL SELECT 'Auditoría (importaciones)', COUNT(*) FROM audit_logs WHERE organization_id=v_org;
END$$
CALL seed_borough_ledger_datos_operativos()$$
DROP PROCEDURE seed_borough_ledger_datos_operativos$$
DELIMITER ;
